"""Check immutable Cooking sources, complete projections and important rule boundaries."""
from pathlib import Path
from fractions import Fraction
import hashlib,json,re

ROOT=Path(__file__).resolve().parents[1];GAME=ROOT.parents[1];AUDIT=GAME/'docs/audit/2026-10-08/full-game'
def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def fraction(d):return Fraction(d['numerator'],d['denominator'])
def rounded(x):return Fraction((x.numerator*100+x.denominator-1)//x.denominator,100)
FOODS={'Meat','Milk','Fruit','Vegetables','Flour','Butter','Honey','Sugar','Eggs','Oil','Bear meat','Fire meat','Poisonous meat','Quetzalcoatlus meat','Sea meat','Vulture meat'}

def main():
    src=read(ROOT/'data/crafting/Decennium_Descent_Crafting_Bible_v4.json');recipes=[r for r in src['recipes'] if r['skill']=='Cooking'];by={r['id']:r for r in recipes}
    evidence=read(AUDIT/'COOKING_SOURCE_EVIDENCE.json');data=read(ROOT/'data/director/cooking_recipe_candidate_internal.json');cards=data['cards'];cb={c['recipeId']:c for c in cards}
    public=read(ROOT/'data/playtest/cooking_recipe_candidate.json')['cards']
    guide=(ROOT/'docs/mechanics/COOKING_RECIPE_PLAYTEST.md').read_text(encoding='utf-8');pmd=(ROOT/'docs/mechanics/COOKING_PUBLIC_RECIPE_CARDS.md').read_text(encoding='utf-8');imd=(ROOT/'docs/director-only/COOKING_INTERNAL_RECIPE_CARDS.md').read_text(encoding='utf-8')
    checks=[]
    def check(name,condition):checks.append({'name':name,'pass':bool(condition)})
    check('All 44 source identities occur once',len(cards)==len(cb)==len(by)==44 and set(cb)==set(by)=={f'recipe-{n}' for n in list(range(81,121))+list(range(632,636))})
    check('Full source evidence exact',recipes==evidence['recipes'])
    check('All 24 protected source and prior-rule artifacts unchanged',len(read(AUDIT/'COOKING_REVIEW_BASELINE.json')['files'])==24 and all(sha(GAME/p)==h for p,h in read(AUDIT/'COOKING_REVIEW_BASELINE.json')['files'].items()))
    check('V4 hash and source indices exact',data['sourceSha256']==evidence['sourceSha256']==sha(ROOT/'data/crafting/Decennium_Descent_Crafting_Bible_v4.json') and all(src['recipes'][c['sourceRecipeIndex']]==by[c['recipeId']] for c in cards))
    check('30 public cards are the exact source subset',len(public)==30 and public==[c for c in cards if c['visibility']=='public'] and {c['recipeId'] for c in public}=={r['id'] for r in recipes if r['visibility']=='public'})
    check('Two restricted and twelve Director formulas stay internal',sum(c['visibility']=='restricted' for c in cards)==2 and sum(c['visibility']=='director-only' for c in cards)==12 and all(c['name'] not in guide+pmd for c in cards if c['visibility']!='public'))
    check('All 30 V5 public-book effects match',len(evidence['publicBookBindings'])==30 and all(b['effectMatches'] and b['paragraphs'][1]['text']=='Effect. '+by[b['recipeId']]['effects'] for b in evidence['publicBookBindings']))
    check('Names, visibility, effects, mechanics, tags and legacy fields preserved',all(c['name']==by[c['recipeId']]['name'] and c['visibility']==by[c['recipeId']]['visibility'] and c['sourceEffect']==by[c['recipeId']]['effects'] and c['sourceMechanics']==by[c['recipeId']]['mechanics'] and c['sourceRecipeTags']==by[c['recipeId']]['tags'] and c['sourceLegacyFields']=={k:by[c['recipeId']][k] for k in ['legacyName','legacyEffect'] if k in by[c['recipeId']]} for c in cards))
    keys=['skill','skillLevel','difficulty','tier','rarity','quantity','craftingTime','workRequirements','craftingCheck','discovery','components','economy','skillProgression']
    check('Every requirement and component occurrence preserved',all(c['sourceRequirements']=={k:by[c['recipeId']][k] for k in keys} for c in cards))
    check('Only explicit current mechanics.tag creates active recipe tags',all(c['operational']['effect']['recipeTags']==([by[c['recipeId']]['mechanics']['tag']] if 'tag' in by[c['recipeId']]['mechanics'] else []) for c in cards) and cb['recipe-633']['operational']['effect']['recipeTags']==[])
    check('Magical nonspell effects preserve exact temporary HP',all(c['operational']['effect']['magical'] and not c['operational']['effect']['spell'] and not c['operational']['effect']['concentration'] and c['operational']['effect']['temporaryHP']==by[c['recipeId']]['mechanics']['temporaryHP'] for c in cards))
    check('Eating uses both 100 regular-turn Actions and 600 seconds',all(c['operational']['activation']['activeMinutes']==10 and c['operational']['activation']['regularTurnActions']==100 and c['operational']['activation']['minimumElapsedSeconds']==600 and not c['operational']['activation']['additionalActionAfterRequiredCount'] for c in cards) and 'no 101st Action' in guide)
    check('One continuous paid serving; interruption leaves old feast',all(c['operational']['activation']['oneEaterOrFeederThroughout'] and c['operational']['activation']['recipientLocked'] and c['operational']['activation']['servingSpentAtLegalStart'] and c['operational']['activation']['noBenefitBeforeCompletion'] and c['operational']['activation']['interruptionLeavesOldFeast'] for c in cards))
    check('Parent clocks preserve 633 eight hours versus rest endpoints',all(c['operational']['effect']['parentDurationSeconds']==(28800 if c['recipeId']=='recipe-633' else None) and c['operational']['effect']['parentEndsAtNextBeneficialLongRest']==(c['recipeId']!='recipe-633') for c in cards))
    check('Explicit secondary durations match source prose',all(c['operational']['effect']['riderDurationSeconds']==(int(m[1])*3600 if (m:=re.search(r'for (\d+) hours?',c['sourceEffect'])) else None) for c in cards))
    check('Riders end with parent, never from depleted shield',all(c['operational']['effect']['riderEndsWithParent'] and not c['operational']['effect']['shieldDepletionEndsRider'] for c in cards))
    check('All-or-none replacement preserves unrelated temporary HP','accept all new feast magic' in guide and 'Remove remaining temporary HP only if the active grant actually belongs to that old feast' in guide and 'an equal or smaller offer is discarded' in guide and 'No RP, temporary HP, trait or other rider can be taken from a declined feast' in guide)
    expected={'damage-resistance':10,'poison-save-advantage':5,'athletics-bonus':4,'poison-disease-save-advantage':5,'rp-recovery':2,'movement-speed':3,'constitution-save-bonus':3,'first-charm-fear-save':1,'prone-defense-advantage':6,'swim-speed':4,'stealth-bonus':1}
    check('All eleven rider families account for all 44 cards',{k:sum(c['operational']['effect']['kind']==k for c in cards) for k in expected}==expected)
    check('RP 88 and 103 restore exactly one real expended RP without invented rest cap',all(cb[f'recipe-{n}']['operational']['effect']['rpRestored']==1 and cb[f'recipe-{n}']['operational']['effect']['requiresExistingRpPool'] and cb[f'recipe-{n}']['operational']['effect']['cappedAtActualRpMaximum'] and cb[f'recipe-{n}']['operational']['effect']['oncePerRestLimit'] is None and not cb[f'recipe-{n}']['operational']['effect']['convertsOtherResources'] for n in [88,103]))
    check('Walking and dynamic swimming do not grant unrelated movement or breathing',all(cb[f'recipe-{n}']['operational']['effect']['walkingSpeedBonusFeet']==10 and not cb[f'recipe-{n}']['operational']['effect']['independentOtherModesIncreased'] for n in [89,91,117]) and all(cb[f'recipe-{n}']['operational']['effect']['dynamicallyRecalculated'] and not cb[f'recipe-{n}']['operational']['effect']['waterBreathing'] and not cb[f'recipe-{n}']['operational']['effect']['createsWalkingMode'] for n in [104,105,107,111]))
    check('Exact skill and unrestricted CON bonuses preserved',all(cb[f'recipe-{n}']['operational']['effect']['skillCheckBonus']==b for n,b in [(83,1),(94,1),(118,3),(632,1),(115,2)]) and all(cb[f'recipe-{n}']['operational']['effect']['saveBonus']==b for n,b in [(90,1),(109,2),(634,3)]) and 'including concentration or Wound/Injury' in guide)
    check('First charm/fear and Prone defenses have actual roll boundaries',cb['recipe-95']['operational']['effect']['riderUses']==1 and 'even with other advantage' in cb['recipe-95']['operational']['effect']['riderConsumption'] and all(cb[f'recipe-{n}']['operational']['effect']['qualifyingRoll']=='actual check or save whose direct consequence includes becoming Prone' for n in [98,101,108,112,113,120]))
    check('Food and gross masses use exact fractions',all(fraction(c['operational']['physical']['foodWeightLb'])==Fraction(2,3) and fraction(c['operational']['physical']['defaultGrossWeightLb'])==Fraction(7,6) and c['operational']['physical']['defaultPackagingWeightLb']==.5 for c in cards))
    check('Nutrition is exact food-only fractional credit',all(fraction(c['operational']['nutrition']['dailySmallMediumFoodFraction'])==Fraction(1,3) and fraction(c['operational']['nutrition']['dailyLargeFoodFraction'])==Fraction(1,6) and c['operational']['nutrition']['waterFuelOrSupplyCredit']==0 for c in cards))
    accounting=True;maps=True
    for c in cards:
        r=by[c['recipeId']];n=c['operational']['nutrition'];rows=r['components'];mass=sum(Fraction(str(x['weight']))*x['quantity'] for x in rows if x['consumed'] and x['name'] in FOODS);ret=max([Fraction(0)]+[Fraction(str(x['weight'])) for x in rows if x['consumed'] and x['name'] in FOODS and x['role']=='catalyst'])
        std=rounded(max(Fraction(0),Fraction(2*r['quantity'],3)-mass));mx=rounded(max(Fraction(0),Fraction(2*(3*r['quantity']//2),3)-mass+ret))
        accounting &= all(Fraction(str(n[k]))==v for k,v in [('nutritiveInputMassLb',mass),('worstRetainedNutritiveCatalystLb',ret),('standardSupplementaryFoodLb',std),('maximumMasterworkSupplementaryFoodLb',mx)])
        maps &= len(n['sourceComponents'])==len(rows) and all(m['componentIndex']==i and m['componentId']==x['id'] and m['name']==x['name'] and m['countsAsNutritiveInput']==(x['name'] in FOODS) for i,(m,x) in enumerate(zip(n['sourceComponents'],rows)))
    check('All 44 supplementary-food reservations independently recompute exactly',accounting)
    check('Occurrence-specific edibility maps preserve all ingredient identities',maps)
    check('All possible output dispositions and nutritional deficits reserved before roll',all(c['operational']['craft']['maximumYield']==3*by[c['recipeId']]['quantity']//2 and c['operational']['craft']['maximumYieldNutritionReservedBeforeCheck'] and c['operational']['craft']['maximumYieldOutputDispositionReservedBeforeCheck'] for c in cards) and 'Any remainder needing to be stored still requires reserved capacity' in guide)
    check('Crock price, weight, capacity and structural profile exact',all(data['newContainer'][k]==v for k,v in {'referencePriceCp':20,'emptyWeightLb':.5,'capacityQuarts':1,'maximumServings':1,'AC':13,'HP':2,'reusable':True,'preservationBonus':False}.items()))
    check('Source economies unchanged and exact unit ratios retained',all(c['operational']['value']['standardBatchReferenceGp']==by[c['recipeId']]['economy']['recommendedMarketValue'] and fraction(c['operational']['value']['unitReferenceGp'])==Fraction(by[c['recipeId']]['economy']['recommendedMarketValue'],by[c['recipeId']]['quantity']) and c['operational']['value']['extraFoodAndPackagingOutsideSourceEconomics'] and c['operational']['nutrition']['supplementaryRationReferenceCpPerLb']==25 for c in cards))
    check('15-minute binding is included; one-year source null preserved',all(c['operational']['craft']['firstBindingPhaseMinutes']==15 and c['operational']['craft']['phaseIncludedInWork'] and c['operational']['craft']['sourceActiveWorkHours']==by[c['recipeId']]['workRequirements']['activeWorkHours'] and c['operational']['craft']['operationalActiveWorkHours']==(1920 if c['recipeId']=='recipe-120' else by[c['recipeId']]['workRequirements']['activeWorkHours']) for c in cards))
    check('Finished meals spoil at 24 unprotected hours with legal-start commitment',all(c['operational']['physical']['shelfLifeSeconds']==86400 and c['operational']['physical']['spoilsWithoutDegradedStage'] and c['operational']['physical']['consumptionNeedOnlyStartBeforeShelfDeadline'] for c in cards) and 'Opening or repackaging never resets age' in guide)
    check('Flawed quantity batches floor; rest singleton batches fail',all(c['operational']['craft']['flawed']==({'mode':'half-batch-quantity','quantity':by[c['recipeId']]['quantity']//2} if by[c['recipeId']]['quantity']>=2 else {'mode':'treat-as-Failed','quantity':0,'materialRecoveryPercent':25}) for c in cards if c['recipeId']!='recipe-633'))
    check('Quality is limited to yield or dedicated packaging, never potency',all(c['operational']['craft']['durabilityOnlyDedicatedMundanePackaging'] and c['operational']['craft']['standardQuantityOnlyWhenDurabilityChosen'] and c['operational']['craft']['mealCrockQualityMaxHP']==3 and not c['operational']['craft']['potencyImproved'] for c in cards) and 'cannot be repeatedly compounded' in guide)
    check('Only 632, 634 and 635 require whole-creature profiles',{c['recipeId'] for c in cards if c['operational']['traitRider']}=={'recipe-632','recipe-634','recipe-635'})
    check('Whole-creature profile requires actual donors and predeclared eligible trait before work',all(c['operational']['traitRider']['requiresVerifiedDonorProvenanceBeforeWork'] and c['operational']['traitRider']['requiresPredeclaredApprovedTraitBeforeWork'] and c['operational']['traitRider']['missingEligibleProfilePreventsWorkStart'] and not c['operational']['traitRider']['unreviewedOtherPassiveTraitsAllowed'] for c in cards if c['operational']['traitRider']))
    check('Whole-creature Masterwork trait is additional and has bounded duration',all(c['operational']['traitRider']['trigger']=='actual Masterwork margin at least 10; natural 1 never qualifies' and c['operational']['traitRider']['additionalToGenericQualityChoice'] and c['operational']['traitRider']['durationSeconds']==3600 and c['operational']['traitRider']['endsWithParentFeast'] for c in cards if c['operational']['traitRider']))
    f=cb['recipe-633']['operational']['failureOverride']
    check('633 alone has contaminated failure without recovery or successful feast',all((c['operational']['failureOverride'] is not None)==(c['recipeId']=='recipe-633') for c in cards) and f['servings']==1 and f['materialRecoveryPercent']==0 and not f['createsFeastRecord'] and f['temporaryHP']==0 and f['beneficialRider'] is None and f['mishapAlsoResolves'])
    check('633 exposure is full meal then DC13 CON one-hour Poisoned only',f['exposureAfterFullConsumptionSeconds']==600 and f['saveAbility']=='CON' and f['saveDC']==13 and f['conditionDurationSeconds']==3600 and f['onFailureCondition']=='Poisoned' and f['damage'] is None and not f['partialConsumptionCreatesExposure'] and not f['coatingOrExtractablePoison'] and f['nutritionCreditIfFullyConsumed'])
    check('Printed card headings and operational effects match JSON exactly',all(imd.count('## '+c['recipeId']+' — ')==1 and '**Operational effect:** '+c['operational']['text'] in imd for c in cards) and all(pmd.count('## '+c['recipeId']+' — ')==1 and '**Operational effect:** '+c['operational']['text'] in pmd for c in public))
    check('No runtime or balance approval inferred',data['runtimeImplemented'] is False and data['balanceApproved'] is False)
    check('Repair 1: supplement remains inventory until actual finished-product outcome',all(c['operational']['nutrition']['reserveBeforeCheck'] and c['operational']['nutrition']['genericSupplementIncorporation']=='after outcome, before finished-serving creation' and not c['operational']['nutrition']['reservationConsumesFood'] and not c['operational']['nutrition']['genericFailedOrMishapWithoutFinishedProductConsumesSupplement'] for c in cards) and 'before creating any finished serving' in guide and 'Reservation does not consume food' in pmd+imd and cb['recipe-633']['operational']['nutrition']['maximumMasterworkSupplementaryFoodLb']==0)
    check('Repair 2: borrowed movement base composition is exact',all(c['operational']['traitRider']['borrowedSpeedComposition']=={'existingBaseBeforeAdditiveMultiplicativeOrTemporaryModifiers':True,'baseFormula':'max(existing base for the mode, donor printed speed)','createsMissingClimbOrSwimMode':True,'createsMissingWalkingMode':False,'recipientModifiersAppliedOnceInNormalOrder':True,'hardZeroAndHalvingPreserved':True,'donorSpeedIsAdditiveBonus':False} for c in cards if c['operational']['traitRider']) and 'before additive, multiplicative or temporary speed modifiers' in guide and 'base/floor' not in guide)
    check('Repair 3: crock improvement preserves damage deficit and never compounds',all(c['operational']['craft']['qualityDurabilityPreservesDamageDeficit'] and c['operational']['craft']['mealCrockCurrentHPIncreaseOnFirstImprovement']==1 and c['operational']['craft']['mealCrockRepeatedMaximumIncrease']==0 for c in cards) and '2/2 becomes 3/3; damaged 1/2 becomes 2/3' in guide and pmd.count('preserving existing damage; an already-HP-3 crock gains neither again')==30 and imd.count('preserving existing damage; an already-HP-3 crock gains neither again')==44)
    check('Repair 4: immediate consumption is a distinct actual output disposition',all(c['operational']['outputDisposition']['maximumServingSlots']==c['operational']['craft']['maximumYield'] and c['operational']['outputDisposition']['predeclaredBeforeCompletionCheck'] and c['operational']['outputDisposition']['maximumSimultaneousImmediateSlotsPerRecipient']==1 and c['operational']['outputDisposition']['immediateServingCommittedAtCraftCompletion'] and c['operational']['outputDisposition']['invalidImmediateSlotRequiresActualReservedStorage'] and c['operational']['outputDisposition']['missingFallbackPreventsValidCompletionThroughException'] for c in cards) and pmd.count('predeclare actual output dispositions')==30 and imd.count('predeclare actual output dispositions')==44)
    check('Repair 5: recipe-120 source header distinguishes null source and operational year','source crafting time 1 year; source active-work hours unspecified/null' in imd and '**Operational work overlay:** 1 workyear = 1,920 active hours' in imd and cb['recipe-120']['sourceRequirements']['workRequirements']['activeWorkHours'] is None and cb['recipe-120']['operational']['craft']['operationalActiveWorkHours']==1920)
    report={'status':'PASS' if all(x['pass'] for x in checks) else 'FAIL','scope':'Source fidelity, authored projection and boundary checks; not runtime execution or human balance testing.','checks':checks,'failed':[x['name'] for x in checks if not x['pass']]}
    (AUDIT/'COOKING_CANDIDATE_VALIDATION.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(json.dumps({'status':report['status'],'checks':len(checks),'failed':report['failed']}))
    if report['failed']:raise SystemExit(1)

if __name__=='__main__':main()
